script:
(function () {
  'use strict';
  // Operating working capital from the cash conversion cycle.
  //   Accounts receivable = sales x DSO / D;  inventory = COGS x DIO / D;  payables = COGS x DPO / D
  //   (D = 365 or 360 days). Working capital needed = AR + inventory - payables + minimum operating cash.
  //   Cash conversion cycle = DSO + DIO - DPO.
  //   After growth g: sales and COGS x (1 + g), days unchanged, so AR, inventory and payables scale by
  //   (1 + g); the operating cash cushion is held constant. Change = after - today.
  //   One-day levers: 1 day less DSO frees sales / D; 1 day less DIO or 1 day more DPO frees COGS / D.
  // Verified (scratchpad b4biz/wc.test.js) by hand: sales $2,000,000, COGS $1,200,000, DSO 45,
  //   DIO 60, DPO 30, 365 days -> AR $246,575, inventory $197,260, payables $98,630, working capital
  //   $345,205, CCC 75 days; +20% growth -> $414,247 (change $69,041 = 20% of $345,205);
  //   on a 360-day year AR = $250,000 exactly; -100% growth -> $0; DPO longer than DSO + DIO gives a
  //   negative requirement (suppliers fund the business), shown as such rather than an error.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var money2 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });

  function fmt(x) { return Math.abs(x) < 0.5 ? money.format(0) : money.format(x); }
  function signed(x) { return Math.abs(x) < 0.5 ? money.format(0) : (x > 0 ? '+' : '−') + money.format(Math.abs(x)); }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function num(id) { var v = parseFloat(document.getElementById(id).value); return isNaN(v) ? NaN : v; }

  function needs(sales, cogs, dso, dio, dpo, days, cash) {
    var ar = sales * dso / days, inv = cogs * dio / days, ap = cogs * dpo / days;
    return { ar: ar, inv: inv, ap: ap, wc: ar + inv - ap + cash, cash: cash, ccc: dso + dio - dpo };
  }

  function clearBody(id) {
    var body = document.getElementById(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }

  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) { var td = document.createElement('td'); td.textContent = text; tr.appendChild(td); });
    body.appendChild(tr);
  }

  function clearResults() {
    ['wcNow', 'wcCcc', 'wcNext', 'wcChange', 'wcPerDollar', 'wcDsoDay', 'wcDioDay', 'wcDpoDay'].forEach(function (id) { set(id, '–'); });
    ['wcNowNote', 'wcCccNote', 'wcNextNote', 'wcChangeNote'].forEach(function (id) { set(id, ''); });
    clearBody('wcTable');
  }

  function update() {
    var sales = num('wcSales'), cogs = num('wcCogs'), dso = num('wcDso'), dio = num('wcDio'), dpo = num('wcDpo'),
        g = num('wcGrowth'), days = parseInt(document.getElementById('wcBasis').value, 10) || 365, cash = num('wcCash');
    if (document.getElementById('wcCash').value.trim() === '') cash = 0;
    var error = document.getElementById('wcError'), problem = '';
    if (isNaN(sales) || sales <= 0 || sales > 1e12) problem = 'Enter annual sales above $0.';
    else if (isNaN(cogs) || cogs < 0 || cogs > 1e12) problem = 'Enter cost of goods sold of $0 or more.';
    else if ([dso, dio, dpo].some(function (x) { return isNaN(x) || x < 0 || x > 1000; })) problem = 'Enter each day count from 0 to 1,000 days.';
    else if (isNaN(g) || g < -100 || g > 1000) problem = 'Enter sales growth from -100% to 1,000%.';
    else if (isNaN(cash) || cash < 0 || cash > 1e12) problem = 'Enter minimum operating cash of $0 or more.';
    error.hidden = !problem;
    error.textContent = problem;
    if (problem) { clearResults(); return; }

    var f = 1 + g / 100;
    var now = needs(sales, cogs, dso, dio, dpo, days, cash);
    var next = needs(sales * f, cogs * f, dso, dio, dpo, days, cash);
    var change = next.wc - now.wc;

    set('wcNow', fmt(now.wc));
    set('wcNowNote', now.wc < 0 ? 'Negative: supplier credit more than covers receivables and stock.' : 'Receivables plus inventory, less what you owe suppliers' + (cash > 0 ? ', plus your cash cushion.' : '.'));
    set('wcCcc', (Math.round(now.ccc * 10) / 10) + ' days');
    set('wcCccNote', now.ccc > 0 ? 'Days between paying suppliers and collecting from customers.' : 'You collect from customers before you pay suppliers.');
    set('wcNext', fmt(next.wc));
    set('wcNextNote', 'At sales of ' + fmt(sales * f) + ' a year.');
    set('wcChangeLabel', change >= 0 ? 'Extra cash growth ties up' : 'Cash released');
    set('wcChange', fmt(Math.abs(change)));
    set('wcChangeNote', change >= 0 ? 'Funding to arrange (from profit, owners or a credit line) as you grow.' : 'Working capital freed as the business shrinks.');
    set('wcPerDollar', money2.format((now.wc - cash) / sales));
    set('wcDsoDay', fmt(sales / days));
    set('wcDioDay', fmt(cogs / days));
    set('wcDpoDay', fmt(cogs / days));

    var tb = clearBody('wcTable');
    addRow(tb, ['Accounts receivable', String(dso), fmt(now.ar), fmt(next.ar), signed(next.ar - now.ar)]);
    addRow(tb, ['Inventory', String(dio), fmt(now.inv), fmt(next.inv), signed(next.inv - now.inv)]);
    addRow(tb, ['Less: accounts payable', String(dpo), signed(-now.ap), signed(-next.ap), signed(-(next.ap - now.ap))]);
    if (cash > 0) addRow(tb, ['Minimum operating cash', '–', fmt(cash), fmt(cash), signed(0)]);
    addRow(tb, ['Working capital needed', (Math.round(now.ccc * 10) / 10) + ' (cycle)', fmt(now.wc), fmt(next.wc), signed(change)]);
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('wcForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
